TRANSLATIONS.update(EMAIL_TRANSLATIONS)


def main() -> None:
    db = SessionLocal()
    inserted = 0
    for key, langs in TRANSLATIONS.items():
        for lang, value in langs.items():
            db.execute(
                text("""
                    INSERT INTO translations (id, key, lang, value)
                    VALUES (gen_random_uuid(), :key, :lang, :value)
                    ON CONFLICT (key, lang) DO UPDATE SET value = EXCLUDED.value
                """),
                {"key": key, "lang": lang, "value": value},
            )
            inserted += 1
    db.commit()
    db.close()
    print(f"Done: {inserted} translations upserted ({len(TRANSLATIONS)} keys × 3 langs).")


if __name__ == "__main__":
    main()
